INSERT INTO inquiries (id, medical_record_id, chief_complaint_category_id, chief_complaint, history, current_medications, allergy_info, appetite, water_intake, owner_observations, staff_id) VALUES
    ('00000000-0000-0000-0000-000000003401', '00000000-0000-0000-0000-000000003301', '00000000-0000-0000-0000-000000002103', '体を頻繁に掻いている。耳の周りが赤い。',   '3日前から症状が悪化。以前も同様の症状あり（2025年秋頃）。', 'なし', 'ハウスダスト（疑い）', 'normal',    'normal',    '散歩後に特に掻く頻度が増える。フードは変更していない。',           '00000000-0000-0000-0000-000000000301'),
    ('00000000-0000-0000-0000-000000003402', '00000000-0000-0000-0000-000000003302', '00000000-0000-0000-0000-000000002101', '3日前から食事量が半分に減った。',           '特に既往歴なし。室内飼い。',                                 'なし', 'なし',               'decreased', 'normal',    '元気はあるが食欲だけが落ちている。排便は正常。',                   '00000000-0000-0000-0000-000000000302'),
    ('00000000-0000-0000-0000-000000003403', '00000000-0000-0000-0000-000000003303', '00000000-0000-0000-0000-000000002103', '耳を頻繁に掻く。耳垢が多い。',             '過去に外耳炎の治療歴あり（2025年6月）。',                    'なし', 'なし',               'normal',    'normal',    '頭を振る動作が増えた。臭いも気になる。',                           '00000000-0000-0000-0000-000000000301'),
    ('00000000-0000-0000-0000-000000003404', '00000000-0000-0000-0000-000000003304', '00000000-0000-0000-0000-000000002102', '昨日から軟便が続いている。今朝は水様便。', '1ヶ月前にドッグランで遊んだ後に嘔吐あり。',                  'なし', 'なし',               'decreased', 'increased', '食事は通常通り与えたが残す。水はよく飲む。',                       '00000000-0000-0000-0000-000000000301'),
    ('00000000-0000-0000-0000-000000003405', '00000000-0000-0000-0000-000000003305', '00000000-0000-0000-0000-000000002101', '食欲不振と多飲多尿。',                     '前回（2025年12月）の血液検査でBUN軽度上昇を指摘。',          'なし', 'なし',               'decreased', 'increased', 'トイレの回数が増えた。水をよく飲む。毛艶が悪くなった気がする。', '00000000-0000-0000-0000-000000000302')
INSERT INTO clinical_plans (id, medical_record_id, physical_exam, diagnosis_category_id, diagnosis_name_id, diagnosis_details, treatment_policy) VALUES
    ('00000000-0000-0000-0000-000000003501', '00000000-0000-0000-0000-000000003301', '体温38.5℃。耳介・腋窩部に発赤・搔痒痕あり。皮膚のフケ多め。', '00000000-0000-0000-0000-000000001803', '00000000-0000-0000-0000-000000001906', 'アトピー性皮膚炎の再燃が疑われる。二次感染の兆候なし。', 'プレドニゾロン短期投与。薬用シャンプー週2回。2週間後に再診。'),
    ('00000000-0000-0000-0000-000000003502', '00000000-0000-0000-0000-000000003302', '体温38.8℃。腹部触診で異常なし。口腔内正常。脱水なし。',         '00000000-0000-0000-0000-000000001801', '00000000-0000-0000-0000-000000001901', '軽度の胃腸炎が疑われる。',                                   '整腸剤投与。消化の良い食事に変更。3日後に改善なければ再来。'),
    ('00000000-0000-0000-0000-000000003503', '00000000-0000-0000-0000-000000003303', '体温38.3℃。左耳：外耳道に茶褐色の耳垢蓄積。軽度の発赤。',       '00000000-0000-0000-0000-000000001803', '00000000-0000-0000-0000-000000001907', '左耳外耳炎の再発。細菌性を疑う。',                           '耳道洗浄実施。抗生剤点耳薬処方。1週間後に再診。'),
    ('00000000-0000-0000-0000-000000003504', '00000000-0000-0000-0000-000000003304', '体温39.1℃。腹部触診でガス貯留。軽度脱水あり。',                 '00000000-0000-0000-0000-000000001801', '00000000-0000-0000-0000-000000001901', '急性胃腸炎。感染性の可能性も考慮。',                         '皮下補液実施。抗生剤＋整腸剤処方。絶食12時間後、少量ずつ食事再開。'),
    ('00000000-0000-0000-0000-000000003505', '00000000-0000-0000-0000-000000003305', '体温38.2℃。脱水軽度。口腔粘膜やや蒼白。毛艶低下。',             NULL,                                   NULL,                                   '慢性腎臓病（CKD）ステージ2の疑い。血液検査にてBUN・Cre上昇。SDMA高値。', '腎臓療法食への変更。皮下補液（週2回）。2週間後に血液再検査。')
